package com.mengzhihua.crm.sales.controller;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.Opportunity;import com.mengzhihua.crm.sales.service.OpportunityService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/opportunities")public class OpportunityController{private final OpportunityService s;public OpportunityController(OpportunityService x){s=x;}@GetMapping public Result<PageResult<Opportunity>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String keyword){return Result.ok(s.list(page,size,keyword));}@GetMapping("/pipeline")public Result<?> pipeline(){return Result.ok(s.pipeline());}@GetMapping("/{id}")public Result<Opportunity> get(@PathVariable Long id){return Result.ok(s.get(id));}@PostMapping public Result<Opportunity> add(@RequestBody Opportunity x){return Result.ok(s.save(x));}@PutMapping("/{id}")public Result<Opportunity> edit(@PathVariable Long id,@RequestBody Opportunity x){x.setId(id);return Result.ok(s.save(x));}@PutMapping("/{id}/stage")public Result<Opportunity> stage(@PathVariable Long id,@RequestBody Map<String,Object>b){return Result.ok(s.stage(id,b));}@DeleteMapping("/{id}")public Result<Void> del(@PathVariable Long id){s.delete(id);return Result.ok();}}
